/* Authored teaching sequences. These are prose introductions, not generated summaries. */
const moduleConceptPaths={
 foundation:{title:'先把计算机里正在发生的事说清楚',terms:['CPU','进程','线程','I/O'],steps:[
 ['程序运行起来，才有进程','程序是一组处理输入的指令；操作系统负责让程序使用机器。一份正在运行的程序实例叫进程。进程内可以有多条执行路径，称为线程。CPU是执行指令的处理器，内存暂存运行时的数据。'],
 ['计算、保存和传输是不同的工作','进程用CPU做计算，从内存取当前数据，用存储保留文件，通过网络与另一台机器交换信息。读文件、收发网络等输入和输出合称I/O。等待数据或锁时，程序可能很慢，却几乎没有消耗CPU时间。'],
 ['沿这几种对象补基础','下面依次解释运行与等待、内存地址、共享数据的并发访问，以及机器之间的部分失败。先能指出“谁在用什么、谁在等谁”，再学习云平台怎样管理它们。']]},
 compute:{title:'从一个程序，走到云提供的资源',terms:['CPU','进程','服务','内存','云计算'],diagram:'v42-cloud-concepts',steps:[
 ['先有程序和用户请求','程序按规则处理输入，运行中的程序实例叫进程。一个持续接收访问并返回结果的程序，可以对外提供服务。用户的一次查询或提交是一次请求；服务完成它，需要机器提供资源。'],
 ['服务依赖四类基本资源','CPU即中央处理器，负责执行指令；内存保存正在处理的数据，存储让数据在进程退出后仍能保留，网络在不同机器之间传递数据。资源不等于业务：给程序一台机器，不代表用户已经能正确查询。'],
 ['云平台把资源变成可申请的能力','云计算让使用者通过网络按需申请和释放计算、网络、存储等资源。平台可以只提供虚拟机器，也可以继续管理应用的运行环境。下面的服务模型比较的就是平台接管到哪一层、应用团队还要负责什么。']]},
 network:{title:'先认识两端，再看请求怎么过去',terms:['网络','IP','端口','请求'],steps:[
 ['两台机器怎样找到彼此','一次请求是向另一方提交的一份处理委托。网络负责在机器之间传递数据。IP地址标识网络中的通信位置，端口帮助同一台机器把数据交给相应程序。域名是便于人记忆的名字，需要先查成相应的地址记录。'],
 ['地址、路径与访问资格逐层衔接','知道目的地址以后，路由决定数据下一步发向哪里；中间设备可能转发或改写地址。访问控制再判断这条通信是否允许。去程能抵达，还需要正确的返回路径。'],
 ['再解释云网络中的具体对象','下面把这些职责对应到逻辑网络、子网、域名解析、负载均衡和安全策略。每次先问它改变地址、路径、连接还是权限，再看超时和错误，不把“网络不通”当成单一原因。']]},
 'cloud-data':{title:'从一份数据，认识存储、数据库与缓存',terms:['存储','数据库','缓存','事务'],steps:[
 ['数据放在哪里，怎样取回来','存储负责保留字节。文件把字节组织成可命名的内容；数据库进一步按记录和关系组织数据，提供查询与更新接口。选择哪一种，要看程序需要怎样访问和修改数据。'],
 ['读得快和保存正确是两件事','缓存保存可复用结果，减少重复访问原始数据源；它可能比源数据旧。事务把一组数据库操作放进约定的提交边界。复制保存更多运行副本，备份则为找回过去的状态提供材料。'],
 ['先分职责，再比较具体机制','下面依次讲存储接口、访问成本、事务与复制、缓存和恢复。对每种机制都问：它保存哪份数据、何时对谁可见、失败后凭什么找回，而不是先记产品名。']]},
 native:{title:'先有容器，再认识Pod和集群',terms:['容器','Kubernetes','Pod','节点','集群','控制器'],steps:[
 ['程序需要一份可重建的运行环境','进程是一份运行中的程序。容器把它所需的文件、运行配置及隔离和资源约束组织起来。镜像保存创建环境所用的固定内容。Linux是一类操作系统；普通Linux容器仍共享所在机器的系统内核。'],
 ['一台机器变成多台机器，才需要编排','Kubernetes是管理容器化应用的系统。集群是这些管理组件和运行机器组成的整体；提供运行资源的机器称为节点。Pod把一个或多个需要一起运行的容器组成一个管理与调度单位。'],
 ['声明目标，再持续维护实际状态','控制器反复比较期望状态与实际状态，推动创建、替换或调整；调度器为尚未放置的Pod选择节点。下面再介绍工作负载、网络、存储、配置和伸缩，分别说明它们连接哪些对象。']]},
 serverless:{title:'先认识一次函数调用，再谈Serverless',terms:['函数','事件','Serverless','幂等'],steps:[
 ['把一项处理写成有输入输出的函数','函数是一段可调用的程序。事件是“某件事已发生”的记录，例如文件上传完成。触发器把这类事件交给函数处理；执行环境提供运行程序所需的计算和依赖。'],
 ['平台接管机器，业务仍有状态','Serverless是一类让使用者主要交付处理逻辑、由平台管理部分资源供给的方式，并不表示没有服务器。一次事件可能被重复交付，函数也可能执行完业务后才丢失响应。'],
 ['从调用继续走到完成条件','幂等要求重复处理同一逻辑操作时仍符合约定效果。下面先解释执行环境和事件交付，再讨论并发、重试、部分失败与成本，最后用程序区分调用次数和实际业务效果。']]},
 'cloud-delivery':{title:'从源码变更，走到可以恢复的上线',terms:['制品','配置','发布','IaC','GitOps'],steps:[
 ['上线交付的不只是一份源码','源码描述程序；构建把源码和依赖变成可运行的制品，例如镜像。配置决定它在某个环境使用哪些参数和资源。发布是让某一组制品与配置开始处理实际请求的过程。'],
 ['应用版本还要配合资源和数据','资源声明描述希望有哪些机器、网络或服务；把它写成可版本管理的代码称为基础设施即代码，即IaC。数据库结构和数据变化可能跨越多个应用版本，回到旧镜像未必能撤回这些变化。'],
 ['让声明、实际状态与验证相连','GitOps把版本库中的声明作为管理依据，由控制循环持续检查和同步实际环境。下面分别解释构建、部署、声明状态、数据迁移和回退，不把一次命令成功当成用户已恢复。']]},
 'cloud-security':{title:'先分清谁、能做什么、作用于哪里',terms:['身份','认证','授权','租户','凭据'],steps:[
 ['先识别请求来自谁','身份表示用户、服务或工作进程是谁；凭据是向系统证明身份或委托的材料。认证检查这份证明是否满足要求。凭据有效，只回答了其中一关。'],
 ['再判断这次动作是否允许','授权根据身份、动作、目标资源和当前规则判断能否执行。租户是共享平台中具有相应数据与管理边界的一组使用者；属于A的身份不应仅因接口可达就能操作B的数据。'],
 ['沿完整执行路径落实边界','下面再讲身份委托、工作负载身份、网络与进程隔离、审计。每层都说明它保护哪个对象；用允许和拒绝两种结果核对边界，而不是把认证、授权和隔离混成一个词。']]},
 'cloud-capacity':{title:'从来了多少工作，算到需要多少资源',terms:['容量','吞吐','延迟','队列','弹性'],steps:[
 ['先规定工作与计量单位','一次请求是一项工作。请求率是每秒来了多少项；吞吐是每秒实际完成多少项；延迟是某一项从规定起点到终点经过的时间。CPU利用率描述资源忙碌程度，不直接等于这些业务结果。'],
 ['完成赶不上到达，就会积压','队列保存暂时未能处理的工作。容量是系统在指定输入、质量和时间目标下可承担的工作量。到达持续超过完成能力时，等待会增长；扩容生效前也可能形成一段资源缺口。'],
 ['再比较弹性、保护与成本','弹性是随需求调整资源的能力。下面先算工作和队列，再看扩容经过哪些步骤、故障后剩余多少容量，最后比较每份有效产出的成本。先统一单位，才有可比较的数字。']]},
 sre:{title:'从用户结果，认识可靠性和可观测性',terms:['SRE','可靠性','指标','日志','追踪','SLO'],steps:[
 ['先说清用户怎样才算得到服务','可靠性讨论服务在约定条件下是否持续给出可接受结果。SRE是用软件工程方法管理服务可靠性的实践。用户关心查询能否正确返回、是否等得太久，需要先把这些目标写成可测条件。'],
 ['目标和观测承担不同职责','指标是按口径统计的数字，日志记录具体事件，追踪把一次请求经过的调用连起来。服务质量目标SLO规定某个指标在某段时间内应达到什么水平；观测数据用来判断与解释实际表现。'],
 ['由目标走向告警、排障和恢复','下面先定义好坏事件与允许损失，再讨论何时告警、下一次观察怎样排除原因，以及用什么结果确认恢复。机器或进程健康只是证据之一，最终仍回到用户的结果。']]},
 'model-foundations':{title:'从输入和预测，认识模型怎样计算',terms:['模型','参数','训练','推理','token','向量','张量','GPU','损失','梯度','优化器'],diagram:'v42-ai-concepts',steps:[
 ['模型先是一套把输入变成输出的计算','模型按一组计算规则处理数据，其中可被学习调整的数字称为参数。训练利用示例调整参数；推理使用选定参数处理新的输入。这是两种工作过程，不是两种机器。'],
 ['文本要先变成可以计算的数字','词元token是模型处理文本的离散单位，可能是字、词的一部分或其他片段。分词器把文本变成词元编号；嵌入查表把编号变成向量，也就是一组有顺序的数字。把多组数字沿多个方向组织起来，就得到张量。'],
 ['从预测走向训练，再看硬件怎样执行','训练用损失衡量预测与目标的差异；梯度描述参数微小变化对损失的影响，优化器据此调整参数。Transformer是一类常用模型结构，后文将逐层拆开它的计算。GPU是适合并行处理大量数值计算的处理器，负责实际执行这些运算。']]},
 training:{title:'从一次预测，走到一次参数更新',terms:['模型','参数','训练','损失','梯度','优化器','进程'],steps:[
 ['先有模型、数据和要预测的目标','模型把输入变成预测，参数是一组控制计算的可调整数字。训练数据还提供要对照的目标；前向计算得到预测后，损失用一个规定的数值衡量预测与目标的差异。'],
 ['误差怎样影响参数','梯度描述损失对参数的小变化怎样响应；反向传播计算这些影响。优化器根据梯度及自身保存的状态调整参数。完成一次这样的更新，才有后文所说的一步训练进展。'],
 ['一台机器放不下或算得慢，再引入并行','进程是运行中的程序实例。多个训练进程可以分担数据、模型或状态，并交换必要的数值。下面先说明每份状态和每个进程的职责，再讲显存、通信、数据供给和恢复。']]},
 platform:{title:'从一个模型，走到可使用的训练和推理服务',terms:['模型','训练','推理','作业','调度','缓存'],steps:[
 ['区分制作模型和使用模型','模型由计算结构、参数及解释输入输出所需的文件共同组成。训练根据数据调整参数；推理使用某个已选版本给新输入产生结果。把两者放到云上，还需要资源、数据和运行管理。'],
 ['平台管理一组有明确身份的运行','一次作业是平台受理的执行委托，包含代码、数据、资源与完成条件。调度决定工作何时使用哪些资源。平台要记录实际运行、失败和产物，才能把一次提交连接到最终可用的模型。'],
 ['在线回答还有新的等待和状态','文本生成通常先处理已有输入，再逐步生成新词元；缓存保存可复用的中间计算结果。下面按训练作业、资源分配、生成、缓存、性能和发布展开，逐步说明为什么训练与在线推理的管理方式不同。']]},
 agent:{title:'先认识任务、模型、工具和执行系统',terms:['任务','模型','工具','运行时','状态','Agent'],diagram:'v42-agent-concepts',steps:[
 ['用户要的是一个可判断的结果','任务写明用户的目标、允许范围和完成条件。模型是根据输入产生输出的计算程序；它可以提出下一步建议，但一段“已经完成”的文字并不等于目标资源已经改变。'],
 ['提议需要由程序变成实际动作','工具是一段可被调用、可读取资料或执行动作的代码。运行时负责接收模型提议、核对参数与权限、调用工具并保存结果。状态记录执行到了哪里、哪些结果已确认，用来支持后续推进和恢复。'],
 ['用一个循环把四者连接起来','Agent系统在任务范围内反复经历提议、检查、执行、观察和验收。下面先讲这条循环，再介绍重试、接管、权限、上下文、检索和评估。Kairo作为后续接入对象，具体能力需要目标系统中的执行证据。']]}
};

const chapterConceptPaths={
 'linux-resource':{terms:['CPU','进程','线程','I/O'],steps:[
 ['程序、进程和线程是怎样接上的','程序描述要执行的指令；运行起来的一份程序实例叫进程。进程内可以有多条执行路径，称为线程。CPU负责执行指令，操作系统决定哪些线程此刻得到执行机会。'],
 ['得到CPU之前，也可能在等别的东西','内存保存当前数据，文件和网络提供输入输出，合称I/O。线程等待数据、锁或执行机会时，经过的时间仍会增加，却不一定消耗CPU时间。'],
 ['用两笔时间解释“慢”','本章把真正使用CPU的时间和外部经过的时间分开，再看进程、线程及资源限制怎样影响一次请求。先找等待发生在哪里，再决定是否增加机器或线程。']]},
 'virtual-memory-oom':{terms:['进程','内存','虚拟内存','OOM'],steps:[
 ['先分清程序看到的地址和机器里的内存','进程是运行中的程序实例。它使用的地址属于自己的虚拟地址空间；操作系统再把这些地址关联到实际内存或其他受支持的存放位置。这套地址管理机制称为虚拟内存。'],
 ['申请空间、实际使用和资源限制不是同一个数','申请了一段地址，不等于已经为每个位置准备实际内存。进程访问数据后，实际驻留页面与记账量可能增加；所在容器或进程组还可能受到独立的内存上限约束。'],
 ['再判断是谁因为什么终止了程序','OOM表示内存不足。本章沿地址映射、页面分配、使用记账和限制解释OOM，并区分申请成功、机器尚有空闲与任务仍被终止为何可能同时出现。']]},
 'concurrency-pools':{terms:['任务','线程','并发','锁','线程池','队列'],steps:[
 ['先有任务，再有处理任务的执行者','任务是一份待完成的工作，线程是程序中的一条执行路径。并发表示多份工作在一段时间内交错推进，不保证它们每一刻都同时执行。'],
 ['共享数据和有限执行者产生两种等待','锁用来保护需要排他访问的共享状态；线程池保存一组可复用的工作线程，队列保存暂时等不到执行者的任务。等锁、等线程和等数据库连接是不同位置的等待。'],
 ['沿任务路径判断哪里需要保护、哪里需要限制','本章先解释共享数据的竞态，再追踪锁与不同队列的关系。把任务数、执行者数和下游容量分别核算，才能判断增加线程是否有用。']]},
 'distributed-systems':{terms:['请求','超时','重试','幂等','事务'],steps:[
 ['一项业务会跨过多台机器','请求是程序交给另一方处理的一次调用。发送、处理和返回响应分别发生，网络或进程可以在其中任一步失败，所以调用方看到的结果与接收方的实际状态可能不同。'],
 ['等待结束，不等于业务一定没做','超时表示在规定时间内没有等到所需结果；重试是再次发起调用。事务只对它实际保护的状态提供提交规则，不能自动把网络两端和任意外部动作包成一个整体。'],
 ['重复调用要围绕同一个逻辑动作','幂等要求重复处理同一逻辑操作时仍符合约定效果。本章用稳定的操作身份、查询结果和接收方记录，解释何时可以重试、何时必须先核对。']]},
 'cloud-overview':{terms:['服务','请求','CPU','内存','存储','云计算'],steps:[
 ['从用户的一次访问认识服务','服务是持续接收访问并返回结果的程序能力；用户的一次查询或提交称为请求。服务程序运行在机器上，离开机器提供的资源，就不能实际处理工作。'],
 ['服务依赖的资源各有分工','CPU执行指令，内存放当前数据，存储保留需要留下的内容，网络连接不同程序和机器。身份与权限再决定谁能使用哪份数据和能力。'],
 ['云平台接管的是其中哪些工作','云计算让资源可以通过网络按需申请和管理。本章沿一条请求把资源、服务、数据与平台连接起来，再比较平台和应用团队各自负责的部分。']]},
 'cloud-compute':{terms:['CPU','进程','内存','虚拟机','容器','容量'],steps:[
 ['先认识要运行的程序和承载它的机器','进程是一份正在运行的程序。CPU执行它的指令，内存暂存它处理的数据。机器的核心数和内存大小描述资源，不直接说明程序每秒能完成多少业务。'],
 ['虚拟化改变资源以什么形式交给程序','虚拟机提供一份可运行客户机操作系统的虚拟机器；普通容器组织并约束进程，同时共享所在机器的内核。两者可以叠放，使用者可控制的对象和资源限制位置并不相同。'],
 ['再从工作量计算候选规格','容量是系统在规定输入与目标下可承担的工作量。本章先讲资源形态与供给保证，再区分CPU时间、等待和并发，用这些关系估算规格并验证。']]},
 'vpc-network':{terms:['网络','IP','端口','DNS','路由','VPC'],steps:[
 ['一次访问要找到机器和程序','网络传递数据；IP地址表示通信位置，端口帮助数据抵达某个程序。域名是便于人记忆的名字，域名系统DNS负责把名字查成相应的记录。'],
 ['找到地址以后，还要有路和访问资格','路由决定数据下一步往哪里发送，访问规则决定是否放行。云中的虚拟私有网络VPC为一组资源提供逻辑网络范围，子网再组织其中的地址和放置范围。'],
 ['沿去程和回程理解每个对象','本章先把名字、地址和连接端点分开，再画路由、转换、代理和返回路径。每一步说明改变了哪一层，而不是只凭一个地址判断服务可用。']]},
 'network-diagnosis':{terms:['请求','连接','TCP','HTTP','延迟'],steps:[
 ['先把一次请求放到一条连接上','请求是应用层的一次工作委托；连接是两端维持通信状态的一种方式。TCP提供可靠、有序的字节传输，HTTP则规定一类应用请求和响应怎样表达。一次读取不必对应一条完整消息。'],
 ['一次等待包含不同阶段','连接建立、接收首个响应字节和接收完整内容有先后关系。延迟是选定起点到终点的耗时，换了观察边界就换了测量对象。'],
 ['先解释协议，再选择下一次观察','本章从字节、连接与关闭开始，再把客户端时间戳对应到各阶段。每项探测都要能区分两种解释，不能因“超时”就直接认定网络或数据库故障。']]},
 'training-storage':{terms:['存储','文件','对象存储','吞吐','IOPS'],steps:[
 ['程序要保存的是字节，要使用的是有组织的数据','存储负责保留内容。块存储向程序暴露可寻址的数据块；文件系统把数据组织成文件与目录；对象存储通过键来存取对象。三种接口能做的操作不同。'],
 ['访问方式决定应该比较哪一种成本','吞吐是每秒传了多少字节；IOPS是每秒完成多少次操作；延迟是一次访问花多久。大块连续读取和许多小块读取，可能在这些指标上表现不同。'],
 ['从实际访问走到选型和验证','本章先区分接口与访问语义，再比较缓存、分片、范围读取和完整性。训练数据只是贯穿的输入例子，存储的对象与单位先于具体案例解释。']]},
 'database-index-locks':{terms:['数据库','表','SQL','索引','事务','锁'],steps:[
 ['先认识表、记录和一次查询','数据库组织可查询和修改的数据；表用一行行记录表达对象，SQL是向数据库表达查询与更新的一种语言。一次业务请求可能先等连接，再执行若干条SQL。'],
 ['找记录、保护修改和保存结果各有机制','索引是帮助定位记录的数据结构；事务规定一组操作的提交边界；锁控制某些数据的并发访问。用了索引，不等于已经避免排序，也不等于事务不会等待。'],
 ['沿执行计划和数据可见性继续推理','本章先判断查询怎样定位和排序，再讲事务读到哪一版、写入为何等待，最后用真实SQL比较结果与计划。业务更新是否正确还要另外核对。']]},
 'cache-consistency':{terms:['缓存','数据库','版本','TTL'],steps:[
 ['先找到原始数据和用于加速的副本','数据库保存业务记录，缓存保存可以复用的结果，减少重复读取或计算。一次更新之后，这两处不一定在同一时刻显示同一内容。'],
 ['版本表达新旧，过期时间表达保留多久','版本用于区分一次次数据变化；TTL表示缓存项被允许保留的时间。删除缓存后，较早开始的读取仍可能带着旧数据回来，因此过期或删除本身不能证明数据已经最新。'],
 ['按读者需要选择一致性承诺','本章先画更新、失效和回填的时序，再讲版本水位、合并回源和故障保护。对允许稍旧的列表和必须确认刚刚写入的用户，分别规定可验证的读取结果。']]},
 'storage-recovery':{terms:['版本','提交','快照','备份','恢复'],steps:[
 ['文件存在和一份结果可交付并不相同','版本标识一组特定内容；提交表示按约定让这组内容成为可供读者使用的结果。多个文件分别写完，不会自动组成一份完整且一致的版本。'],
 ['找回过去，需要知道保存了哪个状态','快照记录某个时点的存储状态；备份保存可用于恢复的材料；恢复利用这些材料重新得到约定的可用状态。文件摘要可以检查内容是否匹配，却不单独证明业务完整。'],
 ['把发布点和恢复点一起核对','本章先解释版本清单与提交，再追踪校验、备份和恢复。读者最终应能说明用户会读取哪份结果，以及失败后怎样避免读到半成品。']]},
 'container-runtime':{terms:['进程','容器','镜像','内核','namespace','cgroup'],steps:[
 ['先有运行中的进程和管理机器的系统','进程是一份运行中的程序。操作系统管理执行、内存和设备，内核是其中直接承担这些职责的核心部分。普通Linux容器内的进程仍由所在机器的内核管理。'],
 ['容器把内容、视图和资源限制组合起来','镜像保存创建环境所需的文件；容器是按镜像与运行配置启动的实例。namespace组织进程能看到的对象视图，cgroup对一组进程做资源记账与约束，它们解决不同问题。'],
 ['沿启动、运行和退出解释差异','本章先把这些对象接起来，再看入口进程、文件挂载和资源限制。镜像相同不代表运行输入相同，也不意味着自动获得一份独立内核。']]},
 'kubernetes-basics':{terms:['Kubernetes','集群','节点','Pod','控制器','调谐'],steps:[
 ['先认识集群里被管理的对象','Kubernetes是管理容器化应用的系统。集群由管理组件和运行机器组成，运行机器称为节点；Pod把一个或多个需要一起运行的容器组成一个管理单位。'],
 ['声明描述目标，控制器推动实际变化','用户提交的对象描述期望状态，例如需要三个副本。控制器反复比较期望与实际并尝试缩小差异，这个过程叫调谐。接口受理、节点绑定和业务就绪因此是不同阶段。'],
 ['从对象身份追踪生命周期','本章按一次创建逐步说明管理组件怎样协作，再解释更新、重建与状态观察。先说清对象是否存在、由谁负责推进，再讨论排障。']]},
 'k8s-workloads':{terms:['Pod','控制器','Deployment','Job','就绪'],steps:[
 ['Pod是运行单位，工作负载描述怎样管理它','Pod把需要一起运行的容器组织起来；控制器持续维护一类对象的期望状态。Deployment常用于管理可替换的服务副本，Job常用于需要完成并退出的任务。'],
 ['副本存在，不等于能够接用户请求','就绪表示应用满足接收相应流量的条件。副本数量、进程运行、健康检查和真实业务结果需要不同证据；一次声明提交成功只是生命周期中的早期一步。'],
 ['再沿创建、更新和排空观察行为','本章把工作负载类型与Pod生命周期连接起来，解释探针、滚动更新和替换。每次都分别检查期望对象、实际实例和用户能否得到结果。']]},
 'scheduling-resources':{terms:['Pod','节点','调度','request','limit','配额'],steps:[
 ['先分清要放置的工作和提供资源的位置','Pod是Kubernetes安排运行的一组容器，节点是提供CPU、内存等资源的机器。调度要从符合要求的节点中为Pod选择位置，并不是把一个Pod的资源随意拆到多台机器。'],
 ['申请、上限与总额度分别约束什么','request是用于放置核算的资源请求，limit是运行时使用的相应上限；配额限制某个管理范围允许申请的总量。通过配额，只说明可以进入相应流程，不保证存在一台能放下它的节点。'],
 ['再把资源与位置条件逐项相交','本章先区分准入、单节点资源和位置规则，再解释优先级、抢占与完成时间。先回答对象卡在哪一关，才有依据决定改声明、换位置还是补容量。']]},
 'k8s-networking':{terms:['Pod','Service','DNS','端口','NetworkPolicy'],steps:[
 ['先认识会变化的实例和稳定的访问入口','Pod是一组一起运行的容器，替换后地址可能变化。Service是为一组后端提供相对稳定访问入口的资源对象；它与某一个应用进程并不是同一个东西。'],
 ['名字、入口和后端通过地址与端口连接','DNS负责名称查询，端口把通信交给相应程序。请求从名字走到入口，再经实现中的转发路径抵达后端；返回方向也要成立。NetworkPolicy表达相应流量允许规则。'],
 ['按每一段路径解释失败','本章分别说明发现、转发、连接状态、策略和回程。解析成功、入口有地址和后端就绪是不同事实，要用能区分这些阶段的观察逐步排查。']]},
 'k8s-storage':{terms:['容器','卷','Pod','PV','PVC'],steps:[
 ['先问数据要比哪一个进程活得更久','容器是应用的一次运行实例。卷把一个存储位置交给应用使用；它的寿命可能不同于容器可写层。Pod把一组容器安排在一起，也不自动替其中的数据提供长期保存保证。'],
 ['需求声明和实际存储资源通过绑定连接','持久卷PV描述集群中的一份存储资源，持久卷声明PVC描述工作负载需要怎样的存储。绑定把两者对应起来；应用还要经过准备、挂载和实际读写才能使用。'],
 ['再逐层判断位置、共享和恢复','本章先定义这些对象，再解释提供存储的驱动、拓扑和访问模式。卷还在、文件还在与业务能正确恢复是三层不同结论。']]},
 'config-secrets':{terms:['配置','密钥','ConfigMap','Secret','凭据'],steps:[
 ['程序文件相同，运行参数仍可能不同','配置是程序运行时使用的参数；密钥等秘密材料需要限制读取范围。Kubernetes用ConfigMap和Secret等对象组织相应数据，程序还需要通过环境变量、文件或接口真正读到它们。'],
 ['保存了新值，运行中的进程未必已经采用','管理对象、挂载文件和进程内存是不同位置。凭据是用于证明身份或授权的材料，更新凭据还要考虑签发方、客户端与接收方怎样兼容。'],
 ['沿传播、重读和撤销解释版本生效','本章先追踪配置怎样到达程序，再讲一致快照、重载和密钥轮换。每个阶段都说明谁持有哪一版，以及用什么观察证明新值实际生效。']]},
 'k8s-autoscaling':{terms:['副本','HPA','指标','request','节点'],steps:[
 ['先认识扩容到底增加了什么','服务副本是同时运行的应用实例；节点是承载它们的机器。增加期望副本数、创建Pod和新增实际处理能力之间，还隔着资源与启动步骤。'],
 ['控制器根据指标推算目标','指标是按口径统计的数字。HPA是自动调整工作负载副本数的控制器；它使用的CPU利用比例常与资源请求request有关，不能只看主机总CPU读数。'],
 ['再把计算结果放回控制时间线','本章先算分母和建议副本，再看指标延迟、节点容量、启动与排队。控制器作出了决定，并不意味着用户立即得到新增容量。']]},
 'serverless-execution':{terms:['函数','事件','触发器','Serverless','幂等'],steps:[
 ['一次函数调用怎样开始','函数是一段有输入输出的可调用程序；事件记录某件事发生了。触发器负责把相应事件交给函数。执行环境提供程序运行所需的计算和依赖。'],
 ['托管环境和业务效果分属不同职责','Serverless让平台接管部分资源管理，使用者交付处理逻辑与规则。平台可能重复交付同一事件；幂等要求同一逻辑操作重复到达时，业务效果仍符合约定。'],
 ['从一次调用走到一批事件的完成','本章按环境、交付、确认、重试与并发逐层展开，再比较部分批次失败与成本。函数返回成功和这项业务是否正确完成，需要明确连接。']]},
 'delivery':{terms:['制品','镜像','配置','发布','回退','IaC','GitOps'],steps:[
 ['先把将要运行的内容固定下来','制品是构建产生的可交付内容，镜像是一类封装应用及其运行文件的制品。配置决定它在目标环境采用什么参数。发布让某一组版本开始处理实际请求。'],
 ['应用变化还会影响资源和数据','IaC表示用代码描述基础设施；GitOps以版本库中的声明驱动环境同步。数据库结构与数据也可能改变，它们不一定随着旧镜像恢复而自动倒退。'],
 ['再讨论渐进替换和兼容恢复','本章先说明交付对象和控制过程，再讲数据迁移、灰度观察与回退。每项回退都要证明旧应用仍能使用当前数据并处理新请求。']]},
 'iam-security':{terms:['身份','认证','授权','凭据','资源','租户'],steps:[
 ['先识别是谁在发起动作','身份表示一个用户、服务或执行进程是谁；凭据是证明身份或委托的材料。认证检查这份证明，而授权判断这个主体能否对指定资源执行指定动作。'],
 ['委托要落到具体目标和范围','资源是受到保护的对象，例如一份报告或一个存储位置；租户是共享平台中的一组管理与数据边界。拿到有效凭据，并不表示可以访问所有租户或所有操作。'],
 ['沿身份链验证最小权限','本章先连接主体、动作和目标，再讲委托、拒绝、凭据轮换与审计。允许和拒绝都要核对实际业务效果，才能说明权限规则生效。']]},
 'elasticity':{terms:['容量','吞吐','队列','弹性','故障域'],steps:[
 ['工作到达和工作完成要分别计数','容量是在指定目标下能承担的工作量，吞吐是单位时间实际完成的工作量。队列保存暂未处理的任务；到达持续超过完成能力时，积压就会增长。'],
 ['新增容量需要经过一段过程','弹性是随需求调整资源的能力。控制信号、资源供应、放置和启动都需要时间。故障域是一组可能因共同原因同时失效的资源，失去它也会改变剩余容量。'],
 ['把用户等待与资源账放在同一条时间线上','本章先解释排队和扩容时序，再计算突发与故障时的余量，最后比较保护机制及成本。扩容目标应是有效完成业务，而不只是把利用率压低。']]},
 'slo':{terms:['SLI','SLO','SLA','错误预算'],steps:[
 ['先定义什么样的结果对用户算好','服务质量指标SLI把用户结果变成可统计的量，例如有效查询中按时正确返回的比例。统计前需要明确哪些请求进入分母、怎样判断好坏以及采用哪个时间窗口。'],
 ['目标、约定和允许损失逐层相连','SLO是对SLI设定的目标；SLA还包含对外约定和相应后果。错误预算是目标允许的坏事件额度，不是随意规定可以故障多少次。'],
 ['再由消耗速度决定行动','本章先把事件与分母算清，再解释预算、消耗率和多窗口告警。指标缺失、没有流量和确实全部成功是不同情况，需要分别处理。']]},
 'observability':{terms:['指标','日志','追踪','剖析','p99'],steps:[
 ['先把一次请求和它的结果说清楚','指标是按规则汇总的数字，日志记录具体事件，追踪连接一次请求的跨组件调用，剖析定位程序的运行成本。这几种观测分别回答不同问题。'],
 ['聚合会保留信息，也会丢失信息','p99是99%分位数。例如按最近秩法，把100次请求耗时从小到大排列，取第99个值。不同组件或不同机器的分位数不能直接拼成全局分位数；标签、采样与时钟又会影响哪些证据能相互连接。'],
 ['先找范围，再解释路径','本章从用户现象进入指标，再用日志、追踪与剖析检验原因。每张图表都说明统计对象和缺失条件，避免把“观测正常”当成业务已经正常。']]},
 'incident':{terms:['故障','指标','假设','时间线','恢复'],steps:[
 ['故障首先是一项用户结果偏离目标','错误增加、请求变慢或结果不正确都可能形成故障，但需要先规定影响的用户、时间窗口和判断口径。指标提供汇总，具体请求和业务状态帮助核对事实。'],
 ['线索还不是原因','假设是对现象的一种可检验解释；时间线把请求、资源和变更按各自观察点连接。一次探测的价值在于它能区分哪些解释，而不是命令数量。'],
 ['沿影响、止损、验证和复盘推进','本章先确定影响，再逐层排除原因并验证恢复。临时缓解、根因修复和后续改进是不同产出，每一步都应有能复查的结果。']]},
 'resilience':{terms:['故障域','备份','恢复','RPO','RTO'],steps:[
 ['先说清可能失去什么、必须找回什么','故障域是一组可能一起失效的资源。备份保存可恢复的历史材料；恢复要把这些材料变成可供用户继续使用的业务状态，而不只是让进程重新启动。'],
 ['数据恢复到哪里，与多久恢复是两条时间轴','RPO规定允许的数据丢失窗口；RTO规定恢复时间目标。多个存储各自最新的状态，不一定属于同一组完整业务提交，需要按实际依赖核对。'],
 ['再把材料、接管和用户验收接起来','本章先明确故障假设与恢复条件，再推导依赖、耗时和旧写者处理。只有用户读写、外部效果和相应服务目标被核对，恢复结论才完整。']]}
};

Object.assign(chapterConceptPaths,{
 'transformer-model':{terms:['模型','参数','训练','推理','token','张量','Transformer'],steps:[
 ['模型先是一套带可调整数字的计算','模型把输入变成输出；参数是其中能够通过数据学习调整的数字。训练利用示例调整参数，推理使用选定参数处理新输入。先区分这两件事，才能知道某份状态为什么需要保存。'],
 ['文本怎样走进数值计算','token是文本经过切分后供模型处理的离散单位。分词器给它编号，嵌入查表把编号变成一组数字。多组数字按多个轴排布形成张量，形状说明每个轴有多大、表示什么。'],
 ['再沿Transformer中的数据路径拆结构','Transformer是一类组织这些计算的模型结构。本章先画从输入到预测的路径，再拆开注意力、前馈和输出，最后说明结构怎样对应参数、计算量与训练状态。']]},
 'tokenization-embedding':{terms:['token','词表','Embedding','向量','logit'],steps:[
 ['文本片段先得到编号','token是模型处理文本的离散单位，不保证刚好对应一个词。词表规定有哪些单位及其编号；分词器按特定规则把文本转换成这些编号。编号的大小本身不代表词义相近。'],
 ['编号通过查表变成一组数字','Embedding即嵌入查表，为每个编号取出一个向量，也就是有顺序的一组数字。模型变换这些表示，输出层再为词表中每个候选计算未归一化得分，称为logit。'],
 ['输入、候选和正确目标分别放在什么位置','本章按编号、向量、得分和预测目标的顺序展开，再解释共享参数与梯度。先对齐每一个位置在预测谁，再计算损失，避免把输入位置直接当成正确标签。']]},
 'attention-mechanics':{terms:['向量','Attention','Query','Key','Value','Softmax','掩码'],steps:[
 ['每个位置先有一组表示自己的数字','向量是一组有顺序的数字。文本中的每个位置可以用向量表示；注意力Attention要做的，是让一个位置按规则从其他可见位置读取信息。'],
 ['查询、匹配依据和取回内容有不同职责','Query是当前位置拿去查询的表示，Key用于与查询匹配，Value是按匹配结果取回的信息。分数经过Softmax变成同一集合内归一化的权重，再对Value加权求和。'],
 ['先规定能看见谁，再讨论怎样并行','掩码规定哪些位置允许参与计算。本章先算一组分数和权重，再解释分头、拼接和共享键值头，始终跟踪每个轴与每个位置的含义。']]},
 'transformer-block':{terms:['向量','Attention','FFN','残差','归一化','Decoder Block'],diagram:'v42-decoder-path',diagramCaption:'采用前置归一化的解码器块。第二次归一化、前馈和第二条残差都以H1为输入；两处归一化各有自己的参数。',steps:[
 ['一个位置的表示怎样继续变化','向量是一组有顺序的数字。模型给每个位置保留这样一组表示；注意力Attention按匹配权重从其他可见位置汇总信息，前馈网络FFN再对各位置分别做变换。'],
 ['分支结果怎样回到原来的表示','残差把输入与计算分支的输出相加；归一化按规定的统计量调整特征尺度。把注意力、前馈、残差与归一化组合起来，就得到这里讨论的一个Decoder Block，即解码器计算块。'],
 ['沿两次相加看清真正的依赖','本章先画每一步接收谁的输出，再分别推导归一化与门控前馈，最后核对参数数和实际实现。张量形状相同，只说明能否相接，不足以证明接线和计算含义正确。']]},
 'position-encoding':{terms:['token','向量','位置编码','RoPE','缓存'],steps:[
 ['内容相同，还需要区分出现的位置','token是文本被切分后的模型处理单位，向量用一组数字表示它。若只按内容做匹配，相同内容未必能提供“在前、在后、相隔多远”的位置线索。'],
 ['位置可以进入表示，也可以进入匹配','位置编码把位置信息加入计算。绝对位置方案可以给表示加上位置向量；RoPE即旋转位置编码，按位置旋转查询和键的成对分量，使点积包含相对位置关系。'],
 ['再把数学位置连接到增量生成','缓存保存可复用的历史中间结果。逻辑位置、缓存中的存放槽位与输入分块方式是不同对象；本章先证明旋转关系，再检查缓存偏移和长度扩展的条件。']]},
 'autograd-training':{terms:['参数','损失','梯度','反向传播','优化器'],steps:[
 ['预测要与明确的正确目标比较','参数是控制模型计算的可调整数字。损失用规定的数值函数衡量预测与正确目标的差异；哪些位置有目标、怎样求平均，决定实际优化的问题。'],
 ['从差异追到哪些参数需要怎样调整','梯度描述损失对参数小变化的响应。反向传播沿计算依赖逐步计算这些影响；优化器再依据梯度及其保存的状态更新参数。算出梯度与真正执行更新是两步。'],
 ['用一次完整更新检验依赖与分母','本章先对齐监督位置，再推导损失、链式法则和共享参数的贡献，最后运行CPU更新。比较的是同一目标下的数值，不以“loss下降了”替代实现正确性。']]},
 'gpu-execution':{terms:['GPU','张量','算子','kernel','线程块','warp'],steps:[
 ['先有要完成的数值工作','张量是按一个或多个轴组织的数字，算子是对这些数字执行的一项运算，例如矩阵乘法。GPU是能够并行处理大量数值工作的处理器，但需要程序明确安排工作与数据。'],
 ['程序怎样把工作交给GPU','kernel是提交给GPU执行的一段设备程序；它组织许多线程，线程再组成线程块及线程束warp等执行单位。模型层、一次算子调用和实际执行的kernel不总是一一对应。'],
 ['从计算位置继续追到数据位置','本章先说明执行层级，再看寄存器、共享内存与显存中的数据移动。先问每份数据被谁使用、保存多久，才能解释占用率、访存和并行能力。']]},
 'roofline-model':{terms:['算子','吞吐','带宽','算术强度','Roofline'],steps:[
 ['一次运算做多少计算、搬多少数据','算子是一项具体数值运算。计算工作量可以按浮点操作数记账，数据移动按字节记账；先固定形状、数据类型和统计边界，才有可以比较的两笔数。'],
 ['处理速度受计算与搬运共同限制','计算吞吐是每秒可完成的运算量，内存带宽是每秒可传输的字节量。算术强度是运算量除以数据移动量；它帮助判断理想条件下更可能受哪一种供给限制。'],
 ['用上界形成假设，再到实际执行中验证','Roofline把这两种能力画成性能上界。本章先推导单位和算式，再讨论复用、融合与调度开销，不把理论上界直接当成程序能达到的速度。']]},
 'flash-attention-io':{terms:['Attention','Softmax','显存','分块','FlashAttention'],steps:[
 ['先认识注意力中的大中间结果','Attention根据查询与键计算匹配分数，再把Value按权重汇总。Softmax将同一行的分数归一化；直接保存所有位置两两匹配的分数，可能形成很大的中间矩阵。'],
 ['计算相同结果，也可以改变保存和读取次序','显存保存GPU可访问的数据；片上空间更小但访问路径不同。分块把大计算拆成可逐段处理的小部分，同时维护合并所需的统计量。'],
 ['再推导怎样分块却保持全局归一化','FlashAttention是一类重排注意力计算和数据访问的算法。本章先解释在线统计怎样合并，再比较中间结果与数据移动，不把减少保存量误说成不再做匹配计算。']]},
 'tensor-parallel-math':{terms:['张量','参数','进程','rank','TP','PP'],steps:[
 ['先分清要切开的数字和执行者','张量按多个轴组织数字，参数是模型可学习的那些数字。进程是一份运行中的程序；同一通信组用rank给进程编号。把工作交给多进程之前，需要先说清每份数据属于谁。'],
 ['切层内计算和切模型层是两种办法','张量并行TP切分某层的矩阵或相关计算；流水线并行PP把不同模型层交给不同阶段。前者需要合并相应局部结果，后者需要把中间表示传给下一阶段。'],
 ['从完整计算推导切分后的通信','本章先保留一个可手算的完整基线，再切矩阵、推导前向和反向，最后核对更新。每次通信都回答它在补齐哪一项计算，而不先背操作名。']]},
 'gpu-cluster':{terms:['模型','参数','训练','GPU','作业','step'],steps:[
 ['先认识一次训练在做什么','模型把输入变成预测，参数是一组可调整数字；训练利用示例计算误差并更新这些参数。GPU是执行大量数值计算的处理器，不是模型本身。'],
 ['脚本交给平台以后成为一次作业','作业是一份包含代码、数据、资源与完成条件的执行委托。平台受理、资源分配、进程启动和真正更新参数，属于不同阶段。一步step在本章按约定的一次参数更新记账。'],
 ['沿同一批数据追到第一次有效更新','本章先固定训练任务，再追踪数据、计算、状态、通信与保存。知道每层负责什么之后，才判断GPU空闲、启动等待或恢复失败应该向哪里查。']]},
 'distributed-training':{terms:['模型','进程','rank','DDP','FSDP','TP','PP'],steps:[
 ['多进程训练要先说明各自拿到什么','模型由结构与参数等内容组成，进程是实际执行训练的程序实例，rank是其在通信组内的编号。可以把输入、参数、梯度或模型层分给不同进程，这些切分不是一回事。'],
 ['不同并行方式连接不同的计算依赖','DDP即分布式数据并行，让各进程处理不同数据并同步梯度；FSDP管理完整分片的数据并行状态。TP切层内计算，PP切模型阶段，分别带来相应的数据交换。'],
 ['先确定容量或时间问题，再选组合','本章先比较每种方法保留什么、计算什么、交换什么，再考虑组合与拓扑。并行名称不直接给出显存峰值或速度，需要回到具体形状和执行时序。']]},
 'gpu-memory':{terms:['GPU','显存','参数','梯度','优化器','激活','dtype'],steps:[
 ['先认识计算设备和模型参数','GPU是适合并行数值计算的处理器，显存是它使用的设备内存。模型参数是控制计算的可调整数字；训练还会产生中间结果，并保存更新参数所需的状态。'],
 ['训练状态分别保存什么','损失衡量预测与目标的差异；梯度描述参数微小变化对损失的影响。优化器依据梯度更新参数，可能另外保存历史状态；激活是前向产生、后续计算可能仍需使用的中间结果。'],
 ['大小、寿命和共享共同决定峰值','dtype表示数字的数据类型，影响每个元素的字节数。逻辑元素、共享存储和设备分配器的读数是不同统计对象；同时存活的对象才共同形成峰值。本章再据此比较混合精度、分片与重计算，不拿固定倍数代替完整预算。']]},
 'ddp-code':{terms:['进程','rank','DDP','梯度','优化器','批次'],steps:[
 ['先把一份输入分给多个训练进程','进程是运行中的程序，rank是它在通信组内的编号。一批样本称为批次。多个进程要先约定谁处理哪些样本，不能仅启动两份脚本就认为数据已经正确切分。'],
 ['同步的是梯度，更新仍由各进程执行','梯度描述损失对参数的影响，优化器据此更新参数。DDP即分布式数据并行，帮助模型副本交换梯度，但输入切分、损失分母和更新次数仍需程序自己保证。'],
 ['按初始化、输入、计算和保存读代码','本章逐段解释一份完整程序，再用小输入核对副本一致与全局目标。先预测每个进程的数据量和更新次数，再运行并比较记录。']]},
 'training-communication':{terms:['进程','rank','进程组','集合通信','NCCL','Gloo'],steps:[
 ['先给参与交换数据的执行者编组','进程是一份运行中的训练程序；进程组规定这次通信由哪些进程参与，rank是组内编号。每个进程都有自己的本地张量，需要按同一约定进入交换步骤。'],
 ['集合通信由一组进程共同完成操作','集合通信让参与者按规则合并或收集数值，例如求和后各自得到完整结果。NCCL与Gloo是可用于相应设备和场景的通信实现；操作的数学含义与底层实现需要分开理解。'],
 ['从结果布局继续追到调用顺序与等待','本章先用小数组算各进程最终得到什么，再解释规模、顺序、重叠和失败。某个进程在等待，既可能来自数据传输，也可能在等其他参与者进入相应步骤。']]},
 'data-pipeline':{terms:['数据集','样本','批次','Dataset','Sampler','worker','rank'],steps:[
 ['训练输入先是一组有身份的样本','数据集组织可供读取的样本，批次把若干样本组成一次计算输入。Dataset描述怎样取样本，Sampler决定怎样选择索引；读取、解码和组批仍是后续步骤。'],
 ['训练进程和读取工作者不要混在一起','rank表示训练通信组中的进程编号，worker是参与数据加载的工作进程或执行者。同一台机器可以有多个训练进程，每个训练进程又可能启用多个加载worker。'],
 ['再把覆盖、供给速度与恢复连起来','本章先核对每份样本被谁读取，再解释尾批次、拼接、预取和恢复。平均速度够快仍可能有抖动，读了多少也不等于已经完成多少有效训练。']]},
 'multinode-lab':{terms:['节点','GPU','进程','rank','DDP','会合'],steps:[
 ['机器、显卡和训练进程是不同数量','节点在本章指参与训练的机器，GPU是设备，进程是实际执行程序的实例。rank给通信组内的进程编号；“两机四卡”还需要说明每台机器启动几个进程。'],
 ['多个进程先找到彼此，再交换训练数值','会合负责让参与者建立这次运行的联系，DDP即分布式数据并行，随后按约定同步梯度。地址可达、设备可用和训练逻辑正确是连续但不同的检查。'],
 ['按最小依赖逐关验收','本章先查设备与环境，再验证小通信、训练、保存和恢复，最后测性能。已有CPU记录与目标GPU手册分别说明，读者按证据逐步进入下一关。']]},
 'checkpoint-recovery':{terms:['检查点','参数','优化器','随机状态','恢复'],steps:[
 ['训练要继续，必须知道停在什么状态','参数是模型当前的可学习数值；优化器可能保存过去更新的历史；随机状态影响之后的随机选择。只有模型权重，未必足够决定下一次训练怎样进行。'],
 ['检查点把相关状态固定在同一个进展位置','检查点是一份可用于继续计算的状态提交，还要关联数据进度和运行配置。恢复读取这份提交，重新构建计算所需的对象，再从约定位置推进。'],
 ['先定义相同，再比较两条训练路径','本章先说明保存对象与边界，再比较连续运行和保存后重启。文件能读、loss相近和完整状态一致，是不同强度的检验。']]},
 'training-performance':{terms:['吞吐','延迟','批次','扩展效率','有效训练'],steps:[
 ['先确定要更快完成哪一项工作','吞吐是单位时间完成的工作量，延迟是指定起终点之间的耗时。训练中的样本、词元、批次和实际参数更新是不同单位，不能混在同一个“每秒速度”里。'],
 ['多加设备之后，工作和目标也要可比','扩展效率比较增加资源后获得多少相应收益。输入规模、有效目标、模型版本、精度、恢复与质量条件若改变，就难以把差异归因到新增设备。'],
 ['再用分段时间检验瓶颈','本章先规定公平比较，再追踪计算、通信、数据和等待。成本最后回到满足目标的有效训练进展，而不是仅用GPU利用率或瞬时峰值评价。']]},
 'kubernetes-training':{terms:['Kubernetes','Pod','Job','进程','DDP'],steps:[
 ['平台对象和训练进程不在同一层','Kubernetes管理容器化应用；Pod是一组一起运行的容器，Job是管理完成型任务的控制对象。训练进程运行在容器中，真正参加模型计算与通信。'],
 ['多个副本不会自动组成一个训练组','DDP即分布式数据并行，要求训练进程约定成员、数据和通信。Job的并行数量只描述平台创建多少执行单元，不自动配置这些应用层关系。'],
 ['再把启动、失败与恢复纳入作业管理','本章先对齐对象、设备和进程，再读单机模板、跨机条件与生命周期。平台重建一个Pod，不代表训练已经从正确检查点继续。']]},
 'training-platform':{terms:['作业','模型','训练','调度','产物'],steps:[
 ['一次提交应有明确的输入和完成条件','训练利用数据调整模型参数。作业是平台受理的一次执行委托，需要关联代码、数据、资源、身份及完成条件，而不只是一段启动命令。'],
 ['平台把委托连接到实际运行和结果','调度安排何时使用哪些资源，执行者真正启动进程，产物是运行产生的可交付文件或记录。受理、运行和合格产物存在，分别需要对应证据。'],
 ['再按生命周期设计管理能力','本章从提交走到资源、输入、保存和模型注册，解释每个对象由谁推进、如何恢复。先把关系走通，再讨论平台选型或组件名称。']]},
 'gpu-scheduling':{terms:['GPU','作业','配额','调度','拓扑','准入'],steps:[
 ['先认识要使用资源的工作','GPU是并行执行大量数值计算的设备，作业是一份明确的运行委托。配额限制某个使用范围可申请或占用多少资源，调度决定具体怎样安排工作。'],
 ['总量之外，还要看资源怎样连接与分布','拓扑描述设备、节点及其连接关系。某项训练可能需要同机多卡或一组同时启动的进程；资源准入判断它是否获准进入相应运行阶段，并不等于所有设备已经就绪。'],
 ['再区分份额、形状、放置和启动','本章先按职责列状态，再用资源碎片与整组预留解释等待。只有每个成员能够按约定协作，分配到的GPU才能形成有效训练。']]},
 'model-serving':{terms:['模型','推理','token','Prefill','Decode','KV Cache'],steps:[
 ['回答由一次次预测逐步形成','模型使用固定版本的参数把输入转换成输出，这个过程称为推理。token是模型处理与生成的离散单位，可能对应字、词的一部分或其他片段。'],
 ['先处理已有输入，再继续生成','Prefill即预填充，一次处理已有提示中的位置；Decode即逐步解码，继续产生新词元。KV Cache是保存历史键和值表示的缓存，用空间换取部分计算的复用。'],
 ['再把生成过程接到资源和用户等待','本章先追踪输入、计算与缓存增长，再讨论组批、量化和调度。先说明每个阶段在做什么，才比较首个输出、后续间隔和可承载请求数。']]},
 'inference-performance':{terms:['推理','请求','TTFT','TPOT','吞吐'],steps:[
 ['用户的一次请求包含多个可观察时刻','推理是使用选定模型处理新输入的计算过程。文本生成请求可能经历提交、接收首个输出、连续输出和结束；客户端与服务端看到的时刻也可能不同。'],
 ['不同指标衡量不同的等待','TTFT是首词元延迟，TPOT是按指定公式计算的后续词元平均间隔；吞吐是同一时间窗口内完成的相应工作量。流式传输块与模型词元不是同一个计数单位。'],
 ['先统一时钟和边界，再比较方案','本章先定义事件与分母，再讨论负载、超时、质量和成本。只挑顺利完成的请求，会漏掉真正影响用户的失败和长等待。']]},
 'ai-lifecycle':{terms:['模型','参数','词表','检查点','推理','发布'],steps:[
 ['一个模型不只有参数文件','参数是控制计算的数字，词表规定文本单位与编号的对应。模型还需要结构、输入输出规则和运行依赖；这些内容配套，程序才能按预期解释同一份输入。'],
 ['继续训练和对外推理需要不同交付对象','检查点保存继续训练所需的状态；推理使用某个完整模型版本处理新请求。发布把一个已验证版本接入实际服务，生产别名则选择当前使用哪个版本。'],
 ['再按层次核对完整、语义和服务能力','本章先定义交付对象，再比较文件校验、加载、语义、任务质量与服务性能。每道检查回答一种问题，回退也要重新验证旧版本可用。']]},
 'agent-runtime':{terms:['任务','模型','工具','运行时','状态','Agent'],steps:[
 ['先把用户要求写成一项任务','任务说明目标、允许范围和完成条件。模型是根据输入生成输出的计算程序，可以提出下一步动作；工具是一段可以实际读取资料或执行操作的代码。'],
 ['提议、执行和结果之间需要运行时','运行时是管理执行过程的程序，负责核对参数与权限、安排工具调用并保存状态。状态记录哪些动作已经确认、哪些结果仍未知，支持下一步推进或恢复。'],
 ['再沿一个受控循环认识Agent','Agent系统把模型提议、工具、状态和任务验收连接成循环。本章先定义每层责任，再解释错误、身份与停止条件，最后进入HTTP和流式参数实战。']]},
 'agent-recovery':{terms:['任务','工具','操作身份','回执','幂等','恢复'],steps:[
 ['先分清用户目标和产生效果的动作','任务是一项待完成的用户委托；工具执行其中的读取或写入。操作身份标识同一个逻辑动作，执行尝试则是为了完成它发起的一次具体调用。'],
 ['调用方没收到响应，效果仍可能存在','回执是接收方对实际处理结果的记录。幂等协议让同一逻辑动作重复到达时仍符合约定效果；恢复利用保存的身份和事实继续推进，不能只依靠聊天文字猜测。'],
 ['再从提交间隙走到多执行者接管','本章先用单执行者解释提交后失联，再增加仍活着的旧执行者。先分别解决重复动作和过期写入，才能说明接管保证从哪里生效。']]},
 'agent-security':{terms:['模型','工具','任务','认证','授权','审批'],steps:[
 ['模型建议做的事，需要由工具真正执行','模型根据输入提出动作，工具是能访问资料或产生效果的程序。任务规定用户允许达到什么目标、使用哪些范围；外部文本只是输入资料，不自动成为新授权。'],
 ['身份、权限和批准是不同判断','认证核对调用者的身份材料，授权判断具体主体能否对目标执行动作。审批为某项特定动作提供额外批准，还要绑定对象和参数，不能把批准过一次当作长期通行证。'],
 ['沿执行边界验证允许与拒绝','本章先连接主体、委托、工具和资源，再讲参数、令牌、撤权和输入诱导。检验拒绝是否有效，要同时查看对应业务效果。']]},
 'agent-memory':{terms:['上下文','运行状态','长期记忆','摘要','版本'],steps:[
 ['同一条信息可以承担三种不同职责','上下文是一次模型调用实际看见的输入；运行状态记录执行过程的可信事实；长期记忆保存供未来任务检索的信息。它们可能谈论同一件事，却不由同一套规则维护。'],
 ['压缩文字，不应该改写已经确认的事实','摘要是保留部分信息的有损表达；版本标识来源在哪一次变化后的内容。把“尚未确认”压成“已经完成”，会同时影响推理和恢复，不能只按字数节省评价。'],
 ['再讨论预算、更新和撤回','本章先把三种存储职责分开，再解释上下文空间、权威事实、摘要版本及记忆撤回。模型视图可以压缩，执行事实仍须按其协议保存与核对。']]},
 'agent-evaluation':{terms:['任务','产物','评分器','试次','尝试'],steps:[
 ['先说明用户目标怎样算完成','任务写明输入、允许动作和期望结果；产物是执行后交付的报告、文件或实际环境变化。评分器是按规则读取这些结果并作判断的程序或评审过程。'],
 ['系统执行和评分判断都可能出错','试次是从规定初态运行一次任务，尝试是试次内部的一次模型或工具调用。系统可能漏做工作，评分器也可能错放行；一次工具成功不能直接当成任务成功。'],
 ['先建立判据，再计算比例与比较版本','本章先规定必要与禁止效果，再检查评分器、分母、样本和预算。最后的统计解释必须能回到具体任务结果，而不只展示一个平均分。']]},
 'kairo-practice':{terms:['Kairo','任务','运行时','工具','接口','验收'],steps:[
 ['先规定准备让系统完成什么','本章把Kairo作为待接入的具体执行系统，而不从名称推定它具备哪些能力。任务需要明确目标、权限范围与完成条件；验收是按这些条件核对实际行为和结果。'],
 ['概念需要对应到真实接口和状态','运行时管理执行过程，工具完成读取或动作，接口规定怎样调用和取得结果。本站的任务身份、回执、恢复和权限要求，需要逐项映射到目标系统的真实对象。'],
 ['再区分契约相容和目标实际完成','本章先写可验证委托，再解释能力映射、记录与反例。本地记录检查不能代替真实接入，目标版本和执行证据齐备后才能确认相应能力。']]},
 'durable-workflows':{terms:['工作流','活动','历史','重放','状态','幂等'],steps:[
 ['先把长期任务拆成有先后依赖的步骤','工作流描述一项任务中步骤怎样推进、等待和结束；活动承担某次外部计算或动作。状态表示执行到了哪里，历史保存已经发生且被确认的事件。'],
 ['从历史重建决定，不等于重复产生效果','重放使用已有历史重新建立执行状态，并复用已记录结果。重新调用外部工具是另一件事，仍需要幂等身份或结果查询，避免同一动作再次产生效果。'],
 ['再分别检查重启、接管和版本升级','本章先建立任务、历史与活动的关系，再解释确定性、提交间隙和过期执行者。不同故障改变不同的事实，不能用一个“恢复成功”概括全部保证。']]},
 'agent-retrieval':{terms:['模型','检索','索引','上下文','RAG'],steps:[
 ['先找到问题需要的资料','模型根据输入产生回答；检索负责从资料中寻找候选内容。索引是为寻找内容组织的数据结构，它反映某次采集和处理的结果，不一定等于资料此刻的全部状态。'],
 ['找到资料，还要交给模型并支持具体主张','上下文是本次模型调用可见的输入。RAG即检索增强生成，把检索材料送入上下文辅助回答；候选排序靠前，不直接证明内容最新、允许访问或支持最终结论。'],
 ['按召回、选择、交付和引用逐层判断','本章先定义片段与版本，再解释中文处理、排序、权限和指标。最终同时核对必要证据覆盖、实际交付的正文与回答中的引用。']]},
 'agent-observability':{terms:['任务','尝试','指标','日志','追踪','回执'],steps:[
 ['一项任务可以包含多次执行尝试','任务是用户的逻辑委托，尝试是为了推进它发起的一次具体调用。多个尝试可能对应同一个业务动作，需要稳定身份才能把它们连接起来。'],
 ['执行路径与实际效果需要不同记录','指标汇总数量与耗时，日志记录具体事件，追踪连接调用的因果路径；回执保存接收方确认的处理结果。路径里有成功跨度，不直接证明用户目标已经完成。'],
 ['再把重试、等待和成本归回任务','本章先建立身份与记录的关系，再解释父子调用、计时和成功任务成本。失败尝试同样消耗预算，不能只在成功轨迹中计算代价。']]},
 'agent-sandbox':{terms:['进程','沙箱','权限','资源预算','生命周期'],steps:[
 ['代码执行需要一个受到管理的环境','进程是一份正在运行的程序。沙箱通过限制它可接触的文件、网络、凭据或系统能力来约束执行环境；不同技术提供的边界和兼容性并不相同。'],
 ['能访问什么，与能消耗多少分别控制','权限规定允许的动作与目标，资源预算规定CPU、内存、时间等使用上限。进程的生命周期还包括启动、派生、取消、退出和清理，不能只检查主进程是否返回。'],
 ['再沿完整启动路径验证边界','本章先说明受保护对象与威胁，再检查继承、路径、资源和清理。限制一个受信子进程的本地实验，不等于已经构成可运行恶意代码的完整隔离系统。']]},
 'training-lab':{terms:['训练','参数','检查点','恢复','DDP'],steps:[
 ['训练进展来自一次次参数更新','训练使用数据调整模型参数；参数之外，优化器历史、随机选择与数据位置也会影响下一次更新。要比较两条训练路径，需要先规定哪些状态必须相同。'],
 ['检查点把继续训练所需的状态提交下来','检查点是一份可用于继续计算的状态保存；恢复重新构建这些对象。DDP即分布式数据并行，本实验由两个实际CPU进程协同执行，两个进程的相关状态都要纳入比较。'],
 ['先预测进度，再运行连续与重启对照','本章把前面机制组合成一条可重复验收：连续四轮，与两轮保存后再两轮，最后比较完整状态。错误配置与只改优化器的反例用来检验检查是否足够强。']]},
 'cloud-service-lab':{terms:['服务','进程','探针','版本','发布','指标'],steps:[
 ['先有实际处理请求的服务进程','服务对外接收请求，进程是它的一次运行实例。版本标识具体程序或配置。机器上的进程存在，不代表当前版本已经能够正确处理用户输入。'],
 ['健康探测与用户结果各自提供证据','探针是按规定发起的健康检查；指标汇总请求和资源表现；发布让某个版本接入实际流量。探针通过、版本切换与业务正确需要分别观察。'],
 ['再从本机运行走向集群验收','本章先执行本地服务、请求与指标，再解释如何把相应信号交给Kubernetes。目标集群手册按其环境继续验证，不把本地结果直接当成集群已运行。']]},
 'production-readiness':{terms:['服务','模型','任务','接口','状态','验收'],steps:[
 ['先写清一条用户请求要得到什么','服务接收请求，模型提供计算结果，Agent任务组织模型与工具完成目标。三者需要的资源、数据和权限相互连接，但各自都有应当独立判断的完成条件。'],
 ['接口连接组件，状态连接执行前后','接口规定组件怎样交换输入输出；状态记录当前进展和已经确认的事实。组合系统需要说明谁拥有事实、谁能修改、失败后从哪里恢复，而不只是画出组件名字。'],
 ['最后按场景逐项验收整条路径','验收是按约定条件核对实际结果。本章先限定目标与边界，再把Cloud、AI和Agent能力接在一起，计算容量并安排失败对照。每条结论都应对应具体输入、观察和用户结果。']]},
 'quantization-serving':{terms:['量化','权重','比例尺','分组','校准'],steps:[
 ['先把“换成整数”写成明确的对应规则','权重是模型中可学习的数字。量化为这些数字规定一套整数表示：比例尺说明每个整数格代表多大，零点说明浮点0对应哪个整数。只有整数而没有这些约定，无法恢复原来的数。'],
 ['粒度、打包和校准分别改变不同的账','分组决定多少权重共用一把比例尺；打包决定多个低比特整数实际占用多少字节；校准用样本选择覆盖的数值范围。它们分别影响误差、文件大小和任务表现，不能混成一个“压缩比”。'],
 ['再分开验收格式、算子与任务质量','本章从两个数的手算开始，推导分组与字节账，比较校准与常见方法，最后运行INT4格式参考与真实CPU INT8执行。数值算对、程序跑通和任务仍正确，是三层独立的证据。']]}
});

Object.assign(chapterConceptPaths,{
 'tcp-event-loop':{terms:['套接字','连接','字节流','消息','就绪'],steps:[
 ['先把程序的入口与双方的连接分开','套接字是程序使用网络通信的对象；操作系统用文件描述符让进程引用它。监听套接字接受新连接，已连接套接字处理某一对通信端点。连接维持双方传输进度，不能直接当成一份业务请求。'],
 ['TCP交付字节，应用自己恢复消息','字节流是一串有顺序的数据。一次发送和一次接收的边界可以不同；消息是应用协议规定的完整处理单位。本章用长度头加中文正文，手算同一段字节怎样在不同接收分段下恢复成两条消息。'],
 ['就绪通知只安排一次尝试','就绪表示此刻可以尝试相应的读写。程序还要解释返回值、保留未完成缓冲，并管理业务执行。本章最后用Linux真实通知与应用就绪队列区分“没有新通知”和“已经没有数据”。']]},
 'mysql-recovery':{terms:['事务','数据页','日志','恢复点','回执'],steps:[
 ['先规定一笔业务的提交边界','事务将一组修改组织成一起提交或回滚的单位；本章让账户余额与一条业务回执共同提交。数据页是引擎组织数据的一种基本存储单位。修改在内存、日志与最终数据页之间经历不同阶段。'],
 ['再按用途拆开日志','日志记录变化或恢复所需信息。撤销日志帮助回滚及读取旧版本，重做日志帮助引擎从崩溃中恢复，二进制日志记录服务器层面的事件历史。本章沿一次提交解释它们怎样配合，避免把三者当成同一个备份。'],
 ['最后明确要恢复哪段历史','恢复点是本次希望重建的历史边界。先取一致的基线，再重放连续日志到完整事务边界，最后用独立回执核对业务。本章特意比较两份余额都正确、回执却不同的结果，解释为何单看查询值还不足够。']]}
});

Object.assign(chapterConceptPaths,{
 'operator-profiling':{terms:['算子','内核','形状','数据类型','布局','归约'],steps:[
 ['先规定对什么数据做什么计算','算子对输入执行一种明确计算，例如矩阵乘法或求和；内核是它的一种底层实现。形状说明每条轴有多长，数据类型说明一个元素怎样表示。先把输入、输出、计算规则和非法输入列全，才能判断两份程序算的是不是同一件事。'],
 ['同一个数学对象，可以有不同布局与合并顺序','布局描述元素在内存中怎样排列，步长描述沿某条轴走一步跨过多少位置。归约把多项合成一项，累加顺序改变时浮点舍入也可能变化。本章先用小数值说明这些差别，再解释连续访问、分块和并行为什么需要额外条件。'],
 ['正确以后，再分开工作量与执行观察','工作量是按形状推导的运算或字节账，执行时间还受实现和机器影响。本章实际编译C代码并读CPU轨迹，先验证结果，再限定测量边界；迁移到GPU时还需对应设备上的实现、同步和硬件证据。']]},
 'moe-routing':{terms:['专家','路由器','门控','归一化','分发','合并','容量'],steps:[
 ['先有多组可选择的计算参数','专家是一份处理隐藏向量的可学习网络，路由器为当前位置计算每个专家的分数并选择其中部分。门控为入选分支规定加权比例；归一化在这里把正权重除以总和，让它们相加为1。它们共同定义一个位置经过哪些参数，不是多个聊天角色自行讨论。'],
 ['打散计算后，还要找回每一份原位置','分发按专家收集输入，合并把结果按原token与入选槽位放回并加权。顺序会在中间改变，身份和权重必须保留。本章用四个二维输入逐项手算，再让两个执行进程乱序回包，验证结果仍回到正确位置。'],
 ['增加容量与设备以后，继续核对同一条数据路径','容量规定每个专家能接收多少分配，偏斜可能让一些专家满载而另一些空闲。跨设备放置又引入搬运和等待。本章先声明准入规则，比较正常与溢出结果，再说明真实GPU专家并行还需要哪些环境与时序证据。']]}
});
